<?php require dirname(__DIR__).'/includes/app.php';require_admin();$notice='';$pages=custom_pages();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';if($a==='save_page'){$id=(string)($_POST['id']??'');$title=trim((string)$_POST['title']);$slug=slugify(trim((string)$_POST['slug']));$data=['id'=>$id?:bin2hex(random_bytes(8)),'slug'=>$slug,'title'=>$title,'eyebrow'=>trim((string)$_POST['eyebrow']),'hero_text'=>trim((string)$_POST['hero_text']),'content'=>(string)$_POST['content'],'cta_title'=>trim((string)$_POST['cta_title']),'cta_text'=>trim((string)$_POST['cta_text']),'cta_label'=>trim((string)$_POST['cta_label']),'cta_url'=>trim((string)$_POST['cta_url']),'seo_title'=>trim((string)$_POST['seo_title']),'seo_description'=>trim((string)$_POST['seo_description'])];$found=false;foreach($pages as $i=>$p)if(($p['id']??'')===$id){$pages[$i]=$data;$found=true;}if(!$found)$pages[]=$data;write_json('pages.json',$pages);$notice='Page saved.';}if($a==='delete_page'){$id=(string)$_POST['id'];$pages=array_values(array_filter($pages,fn($p)=>($p['id']??'')!==$id));write_json('pages.json',$pages);$tabs=read_json('tabs.json',tabs());foreach($tabs as &$t)if(($t['page_slug']??'')===($_POST['slug']??''))$t['page_slug']='';unset($t);write_json('tabs.json',$tabs);$notice='Page deleted.';}}$edit=null;$eid=(string)($_GET['edit']??'');foreach($pages as $p)if(($p['id']??'')===$eid)$edit=$p;$edit=$edit?:['id'=>'','slug'=>'','title'=>'','eyebrow'=>'GALINDOS BUILDERS LLC','hero_text'=>'','content'=>'<h2>Page heading</h2>\n<p>Add your page content here.</p>','cta_title'=>'Ready to get started?','cta_text'=>'Tell us about your project.','cta_label'=>'Request a Quote','cta_url'=>site_url('/#contact'),'seo_title'=>'','seo_description'=>''];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Custom Pages</title><link rel="stylesheet" href="<?=e(asset_url('/admin/admin.css'))?>"></head><body><aside><div class="admin-logo">GB</div><h2>Galindos Builders</h2><a href="<?=e(site_url('/admin/'))?>">Dashboard</a><a href="<?=e(site_url('/admin/pages.php'))?>">Custom Pages</a><a href="<?=e(site_url('/admin/content.php'))?>">Content / SEO / Quotes</a><a href="<?=e(site_url('/'))?>" target="_blank">View Website ↗</a></aside><main class="admin-main"><header><div><small>WEBSITE ADMIN</small><h1>Custom Tab Pages</h1></div></header><?php if($notice):?><div class="success"><?=e($notice)?></div><?php endif;?><section class="panel"><h2><?=empty($edit['id'])?'Create Page':'Edit Page'?></h2><p>Create content here, then assign the page to any navigation tab from the main dashboard.</p><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_page"><input type="hidden" name="id" value="<?=e($edit['id'])?>"><label>Page Title<input name="title" required value="<?=e($edit['title'])?>"></label><label>URL Slug<input name="slug" required placeholder="about-us" value="<?=e($edit['slug'])?>"></label><label>Hero Eyebrow<input name="eyebrow" value="<?=e($edit['eyebrow'])?>"></label><label>Hero Text<input name="hero_text" value="<?=e($edit['hero_text'])?>"></label><label class="full">Page Content (basic HTML supported)<textarea name="content" rows="16"><?=e($edit['content'])?></textarea></label><label>CTA Title<input name="cta_title" value="<?=e($edit['cta_title'])?>"></label><label>CTA Button Label<input name="cta_label" value="<?=e($edit['cta_label'])?>"></label><label class="full">CTA Text<input name="cta_text" value="<?=e($edit['cta_text'])?>"></label><label class="full">CTA URL<input name="cta_url" value="<?=e($edit['cta_url'])?>"></label><label class="full">SEO Page Title<input name="seo_title" value="<?=e($edit['seo_title'])?>"></label><label class="full">SEO Description<textarea name="seo_description" rows="3"><?=e($edit['seo_description'])?></textarea></label><button>Save Page</button></form></section><section class="panel"><h2>Existing Pages</h2><div class="table-wrap"><table><thead><tr><th>Page</th><th>URL</th><th>Actions</th></tr></thead><tbody><?php foreach($pages as $p):?><tr><td><b><?=e($p['title'])?></b></td><td>/page/<?=e($p['slug'])?></td><td><a href="?edit=<?=e(urlencode($p['id']))?>">Edit</a> <a target="_blank" href="<?=e(site_url('/page/'.rawurlencode($p['slug'])))?>">View</a><form method="post" style="display:inline" onsubmit="return confirm('Delete this page?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_page"><input type="hidden" name="id" value="<?=e($p['id'])?>"><input type="hidden" name="slug" value="<?=e($p['slug'])?>"><button class="danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>